WITH filtered AS (SELECT *, TRIM(country) AS clean_country, COALESCE(city, 'OTHER') AS city_clean FROM suppliers WHERE city IS NOT NULL), filtered_suppliers AS (SELECT *, TRIM(city) AS clean_city, COALESCE(city, 'UNKNOWN') AS city_clean_2 FROM filtered WHERE city IN ('New York', 'Chiang Mai')), kept AS (SELECT s.* FROM filtered_suppliers s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND UPPER(c.product_name) LIKE '%OIS%')) SELECT id, supplier_name, city, rating, clean_country, city_clean, clean_city, city_clean_2, CASE WHEN city RLIKE '^(Tokyo|Bangkok)$' THEN 'EXTENDED' WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS city_zone FROM kept;
